-- ==================== 2. CONFIG & STATE ====================
local Config = {
    AutoActive = false,
    TypingDelay = 0.05,     -- Dipercepat agar tidak typo karena lag game
    ScanInterval = 0.5,
    ContinuationOnly = true,
    TargetUI = "",          -- UI yang dikunci (Biar ga baca chat/error)
}

local State = {
    UsedWords = {},
    IndexedDB = {},
    LastPrompt = "",
    TotalDB = #kataKBBI,
    IsTyping = false,       -- Mencegah bot membaca layar saat sedang ngetik/loading
}

local function rebuildIndex()
    State.IndexedDB = {}
    for _, word in ipairs(kataKBBI) do
        local first = word:sub(1,1):lower()
        if not State.IndexedDB[first] then State.IndexedDB[first] = {} end
        table.insert(State.IndexedDB[first], word:lower())
    end
end
rebuildIndex()

-- ==================== 3. ENGINE LOGIC ====================

local function getPrefixList(kata)
    local p = #kata
    local list = {}
    if p >= 3 then table.insert(list, kata:sub(p-2, p)) end
    if p >= 2 then table.insert(list, kata:sub(p-1, p)) end
    table.insert(list, kata:sub(p, p))
    return list
end

local function cariJawaban(awalan)
    awalan = awalan:lower()
    local firstLetter = awalan:sub(1,1)
    local candidates = State.IndexedDB[firstLetter] or {}
    
    for _, kata in ipairs(candidates) do
        if kata:sub(1, #awalan) == awalan and not State.UsedWords[kata] and #kata > #awalan then
            return kata
        end
    end
    return nil
end

local function ketikCerdas(fullWord, prefix)
    State.IsTyping = true -- BUTAKAN MATA BOT
    local textToType = fullWord
    
    -- JIKA ON: Hindari Double Typing (Cuma ketik sambungannya)
    -- Memastikan potongan akurat (Contoh: "ekor" dipotong "ek" = "or")
    if Config.ContinuationOnly and fullWord:lower():sub(1, #prefix) == prefix:lower() then
        textToType = fullWord:sub(#prefix + 1)
    end

    for i = 1, #textToType do
        local char = textToType:sub(i, i)
        local key = Enum.KeyCode[char:upper()]
        if key then
            VIM:SendKeyEvent(true, key, false, game)
            task.wait(0.02)
            VIM:SendKeyEvent(false, key, false, game)
            task.wait(Config.TypingDelay)
        end
    end
    
    task.wait(0.1)
    VIM:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
    VIM:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
    
    -- Tandai kata sudah dipakai, supaya kalau game menolak kata ini, bot akan cari kata LAIN
    State.UsedWords[fullWord] = true
    
    -- JEDA 3 DETIK: Tunggu game memproses jawaban (Ganti giliran/Muncul error)
    -- Selama 3 detik ini, bot tidak akan membaca layar sama sekali!
    task.wait(3) 
    State.IsTyping = false -- BUKA MATA BOT LAGI
end

