})

SetupTab:CreateButton({
    Name = "🔍 SCAN LAYAR SAAT ADA SOAL",
    Callback = function()
        local tempList = {}
        for _, ui in pairs(LP.PlayerGui:GetDescendants()) do
            if (ui:IsA("TextLabel") or ui:IsA("TextButton")) and ui.Visible and ui.Text ~= "" then
                local t = ui.Text:gsub("\n", " ")
                if #t <= 30 and not t:match("^%d+$") then 
                    table.insert(tempList, ui.Name .. " | " .. t) 
                end
            end
        end
        if #tempList > 0 then uiDropdown:Refresh(tempList, true) end
    end
})

