-- ==================== 5. ENGINE SCANNER ====================
task.spawn(function()
    while task.wait(Config.ScanInterval) do
        -- JIKA SEDANG NGETIK ATAU JEDA, JANGAN BACA LAYAR!
        if Config.AutoActive and not State.IsTyping and Config.TargetUI ~= "" then
            local targetText = ""
            
            -- HANYA BACA UI YANG SUDAH DIKUNCI
            for _, ui in pairs(LP.PlayerGui:GetDescendants()) do
                if (ui:IsA("TextLabel") or ui:IsA("TextButton")) and ui.Name == Config.TargetUI then
                    targetText = ui.Text
                    break
                end
            end

            -- PROSES SOAL
            if targetText ~= "" then
                -- Pembersihan Teks (Misal "Soal: MA" -> "MA")
                local cleanText = targetText:match(":%s*(.*)") or targetText
                cleanText = cleanText:match("%a+$") or cleanText:match("%a+")
                
                -- Jika soal berubah, ATAU soal tetap sama tapi bot sudah selesai jeda (artinya jawaban ditolak game)
                if cleanText and (targetText ~= State.LastPrompt or true) then
                    local prefixes = getPrefixList(cleanText)
                    local finalAns = nil
                    local chosenPre = ""

                    for _, pre in ipairs(prefixes) do
                        finalAns = cariJawaban(pre)
                        if finalAns then chosenPre = pre break end
                    end

                    if finalAns then
                        State.LastPrompt = targetText
                        LblDetect:Set("Terdeteksi: " .. cleanText:upper())
                        LblAns:Set("Jawaban: " .. finalAns:upper() .. " (Sisa: ".. finalAns:sub(#chosenPre + 1):upper() ..")")
                        
                        -- Panggil fungsi ketik
                        ketikCerdas(finalAns, chosenPre)
                    else
                        LblAns:Set("Jawaban: Kosong di Database!")
                    end
                end
            end
        end
    end
end)
